plot checked-quantity {
 operation: units/convert-temperature-difference(source = 9°F, to = K)
 show: presentation/bool-value
 operation.receipt >> (variant/is(.result, "converted") ? (.result.converted.coefficient == 5 ? .result.converted.exponent == 0 : false) : false) >> show.value
}.

plot checked-quantity {
 operation: units/convert-temperature-difference(source = 1m°C, to = K)
 show: presentation/bool-value
 operation.receipt >> (variant/is(.result, "converted") ? (.result.converted.coefficient == 1 ? .result.converted.exponent == -3 : false) : false) >> show.value
}.

plot checked-quantity {
 operation: units/compare(left = 1000mm, right = 0.001km)
 show: presentation/bool-value
 operation.receipt >> (variant/is(.result, "equal")) >> show.value
}.

plot checked-quantity {
 operation: units/compare(left = 1°F, right = 0°C)
 show: presentation/bool-value
 operation.receipt >> (variant/is(.result, "less")) >> show.value
}.

plot checked-quantity {
 operation: units/compare(left = 1MB, right = 1MiB)
 show: presentation/bool-value
 operation.receipt >> (variant/is(.result, "less")) >> show.value
}.

plot checked-quantity {
 operation: units/compare-temperature-differences(left = 9°F, right = 5K)
 show: presentation/bool-value
 operation.receipt >> (variant/is(.result, "equal")) >> show.value
}.

plot checked-quantity {
 operation: units/convert(source = 1°F, to = °C)
 show: presentation/bool-value
 operation.receipt >> (variant/is(.result, "refused") ? .result.refused == "inexact" : false) >> show.value
}.

plot checked-quantity {
 operation: units/convert(source = 1Hz, to = m)
 show: presentation/bool-value
 operation.receipt >> (variant/is(.result, "refused") ? .result.refused == "incompatible-dimensions" : false) >> show.value
}.

plot checked-quantity {
 operation: units/convert(source = 1Qm³, to = qm³)
 show: presentation/bool-value
 operation.receipt >> (variant/is(.result, "refused") ? .result.refused == "overflow" : false) >> show.value
}.

plot checked-quantity {
 operation: units/compare(left = 1m, right = 1s)
 show: presentation/bool-value
 operation.receipt >> (variant/is(.result, "refused") ? .result.refused == "incompatible-dimensions" : false) >> show.value
}.
